import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro — de-hardcoding the discovery content tables (round 2)","description":"","frontmatter":{"title":"Retro — de-hardcoding the discovery content tables (round 2)","type":"retro","date":"2026-10-14T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/retros/dehardcode-round2.md","filePath":"vendored/graphopt/project/retros/dehardcode-round2.md"}`),a={name:`graphopt/project/retros/dehardcode-round2.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-—-de-hardcoding-the-discovery-content-tables-round-2" tabindex="-1">Retro — de-hardcoding the discovery content tables (round 2) <a class="header-anchor" href="#retro-—-de-hardcoding-the-discovery-content-tables-round-2" aria-label="Permalink to “Retro — de-hardcoding the discovery content tables (round 2)”">​</a></h1><h2 id="what-the-pass-did" tabindex="-1">What the pass did <a class="header-anchor" href="#what-the-pass-did" aria-label="Permalink to “What the pass did”">​</a></h2><p>Round 1 (plan 0018, <code>dehardcode.md</code>) gave the <em>op</em> vocabulary one registry (<code>mlopt_core.opmeta</code>); plan 0019 declared the <em>ops</em> as data (<code>mlopt_core.opdata</code>). This pass applies the same discipline to the second vocabulary the engine carries: the <em>content tables</em> — the banks, libraries, ledgers and weights a learned policy could plausibly choose — that were still buried as module-level literals in <code>mlopt_discovery/</code> and <code>mlopt_core/meta.py</code>.</p><p>Two new pure-data modules hold them (the <code>opmeta</code> idiom: the table lives in exactly one place, consumers bind the <strong>same object</strong>, and a consistency test pins the relation):</p><ul><li><strong><code>mlopt_core/lawdata.py</code></strong> — the law-side vocabulary the core search machinery reads: the coherence classification (<code>COHERENT_RULE_NAMES</code>), the canonicalizer&#39;s monoid vocabulary (<code>AC_IDENTITY</code>, <code>ASSOC_ONLY</code>), and the bounded instantiation bank (<code>INSTANTIATE_LEAF_SHAPES</code>, <code>INSTANTIATE_ATTR_POOL</code>).</li><li><strong><code>mlopt_discovery/lawdata.py</code></strong> — every discovery-side content table: oracle enumeration banks, verifier instantiation defaults, the gap-synthesis shape pools, the grammar alphabet, training families, the coherence-probe neighbourhoods, the intake ledger, the meta-game arm inventory and prior/score weights, the arena reward composition, and — as <em>term specs</em> — the proposal corpus (<code>SEED_TERMS</code>, <code>GRAMMAR_SCHEMAS</code>, <code>SHAPE_SCHEMAS</code>) and the impact corpus (<code>CANDIDATE_LAWS</code>, <code>SYNTHETIC_CASES</code>).</li></ul><p>Both modules are pure data — no logic, no callables — so adding a bank entry, schema row, arm or weight is a data row, never a Python edit: the shape a model writes a new entry in.</p><h2 id="term-specs-—-how-the-corpora-went-declarative" tabindex="-1">Term specs — how the corpora went declarative <a class="header-anchor" href="#term-specs-—-how-the-corpora-went-declarative" aria-label="Permalink to “Term specs — how the corpora went declarative”">​</a></h2><p>The five term corpora (<code>seed_terms</code>, <code>schema_candidates</code>, <code>shape_proposal.schemas</code>, <code>impact.new_laws</code>, <code>impact.synthetic_cases</code>) were <code>Op.make(...)</code> call lists — executable code carrying content. They are now tuples of <em>specs</em> in the language <code>object_synthesis.term_from_spec</code> reads (<code>str</code> metavariables, <code>int</code>/<code>float</code> constants, <code>(op, *specs[, attrs])</code> nodes), extended with two leaf forms — <code>(&quot;var&quot;, name, dims)</code> / <code>(&quot;param&quot;, name, dims)</code> — for the typed concrete leaves the seed corpus and the grammar candidates carry. One resolver, <code>proposal._spec_term</code>, mints terms; <code>shape_proposal</code> and <code>impact</code> share it. <strong>Every resolved term is byte-identical</strong> to the literal it replaced — verified by replaying the old builders out of <code>git show HEAD:</code> and comparing <code>op_repr</code> on all 16 + 23 + 21 + 11 + 11 entries (and the inputs/feed ordering of every synthetic case).</p><h2 id="what-moved-what-stayed-—-the-inventory" tabindex="-1">What moved, what stayed — the inventory <a class="header-anchor" href="#what-moved-what-stayed-—-the-inventory" aria-label="Permalink to “What moved, what stayed — the inventory”">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Was</th><th>Now</th><th>Moved?</th><th>Why</th></tr></thead><tbody><tr><td><code>oracle._ATTR_KINDS</code> / <code>_ATTR_KIND_OVERRIDES</code></td><td>literal dicts</td><td><code>lawdata.ATTR_KINDS</code> / <code>ATTR_KIND_OVERRIDES</code></td><td>yes</td><td>the attr→value-kind typing a sweep (or a learned enumerator) enumerates — content</td></tr><tr><td><code>oracle._VIEWED_SHAPES</code> / <code>_CHAIN_VIEWED_SHAPES</code></td><td>literal tuples</td><td><code>lawdata.VIEWED_SHAPES</code> / <code>CHAIN_VIEWED_SHAPES</code></td><td>yes</td><td>the shape bank a metavariable-under-a-view enumerates — content</td></tr><tr><td><code>oracle._FREE_SENTINELS</code> / <code>_FALLBACK_AXES</code> / <code>_FALLBACK_SHAPES</code></td><td>literals</td><td><code>lawdata.FREE_SENTINELS</code> / <code>FALLBACK_AXES</code> / <code>FALLBACK_SHAPES</code></td><td>yes</td><td>sentinel + unknown-shape bank entries — content</td></tr><tr><td><code>oracle._CONST_DOMAIN</code></td><td>literal dict</td><td><code>lawdata.CONST_DOMAIN</code></td><td>yes</td><td>per-op literal-constant domain (the domain-gapped rescues of <code>cap-policy.md</code>) — content</td></tr><tr><td><code>oracle</code> tuple sources (<code>_tuple_sources</code> body)</td><td>three <code>Op.make</code> calls</td><td><code>lawdata.TUPLE_SOURCES</code> + <code>TUPLE_SOURCE_SHAPE</code></td><td>yes</td><td>the <code>(op, attrs)</code> spec of each tuple-producing op the getitem corner mints — content; the instantiation stays code</td></tr><tr><td><code>oracle._attr_options</code> per-op branches</td><td>functions of operand shape</td><td>unchanged</td><td>no</td><td>shape-<em>dependent</em> domains are algorithms, not tables; they read the moved static banks</td></tr><tr><td><code>verifier._LEAF_SHAPES</code> / <code>_ATTR_DEFAULTS</code> (+ the <code>S</code>/<code>F</code> scalar corner)</td><td>literal dicts + two <code>elif</code> branches</td><td><code>lawdata.INSTANCE_LEAF_SHAPES</code> / <code>INSTANCE_ATTR_DEFAULTS</code> / <code>INSTANCE_SCALAR_MVARS</code></td><td>yes</td><td>metavariable→shape/default for <code>generic_instance</code> — content; the instantiate/check logic stays</td></tr><tr><td><code>gap_gen._SHAPE_POOL</code> / <code>_BASE_SHAPES</code></td><td>literal lists</td><td><code>lawdata.SHAPE_POOL</code> / <code>BASE_SHAPES</code></td><td>yes</td><td>the instantiation draw pool — content</td></tr><tr><td><code>grammar._BINARY_OPS</code> / <code>_UNARY_OPS</code> / <code>_LITERALS</code></td><td>literal tuples</td><td><code>lawdata.GRAMMAR_*</code></td><td>yes</td><td>the search&#39;s alphabet — the set a schema-space player chooses from</td></tr><tr><td><code>families.FAMILIES</code> / <code>_LINEAR_TRAIN</code> / <code>_LINEAR_HELD</code></td><td>literals</td><td><code>lawdata.FAMILIES</code> / <code>LINEAR_*_SHAPES</code></td><td>yes</td><td>the training/held-out split — the corpus a generalization claim is measured on</td></tr><tr><td><code>coherence._CLUSTER</code>, <code>coherence2._CORPUS_MODELS</code></td><td>literals</td><td><code>lawdata.COHERENCE_CLUSTER</code> / <code>COHERENCE_CORPUS_MODELS</code></td><td>yes</td><td>hand-picked neighbourhoods — content</td></tr><tr><td><code>intake._PURPOSE_BUILT</code></td><td>literal frozenset</td><td><code>lawdata.PURPOSE_BUILT</code></td><td>yes</td><td>the corpus-circularity ledger — already data, now in the one home with the rest</td></tr><tr><td><code>intake.candidates()</code> registry (the corpus spelling list)</td><td><code>Workload</code> records with <code>nn.Module</code> thunks</td><td>unchanged</td><td>mixed</td><td>the <code>Workload</code> <em>rows</em> are already records; their <code>factory</code>/<code>kind</code> hooks carry kernel bodies — code, never data. The pure-metadata half (<code>_PURPOSE_BUILT</code>) moved</td></tr><tr><td><code>impact._model_cases</code> / <code>zoo</code> model registries</td><td><code>nn.Module</code> thunks</td><td>unchanged</td><td>no</td><td>model constructors are kernel bodies — code, never data</td></tr><tr><td><code>meta_game.ENUMERATION_ORDER</code> / <code>CORPUS_ARMS</code> / <code>_ARM_NAMES</code></td><td>literal tuples</td><td><code>lawdata.GENERATOR_ORDER</code> / <code>CORPUS_ARMS</code></td><td>yes</td><td>the generator-arm inventory the guide schedules — enumerable content</td></tr><tr><td><code>meta_game._MV_NAMES</code> / <code>_CONSTS</code></td><td>literals</td><td><code>lawdata.MV_NAMES</code> / <code>CONST_LEAVES</code></td><td>yes</td><td>the construction player&#39;s leaf vocabulary — content</td></tr><tr><td><code>meta_game._PRIOR_*</code> (7 weights)</td><td>literal floats</td><td><code>lawdata.PRIOR_WEIGHTS</code> dict</td><td>yes</td><td>arm/child priors — exactly what a learned policy could choose</td></tr><tr><td><code>meta_game</code> score composition <code>1 + 0.2·fires + 2·paid + 10·drop</code></td><td>literal formula</td><td><code>lawdata.REFEREE_SCORE</code> dict</td><td>yes</td><td>the referee&#39;s scoring weights — content (the composition stays code)</td></tr><tr><td><code>arena._STAGE_CREDIT</code> / <code>_USABLE_BONUS</code> / <code>_FIRE_CREDIT</code> / <code>_PAY_CREDIT</code></td><td>literal floats</td><td><code>lawdata.ARENA_REWARD</code> dict</td><td>yes</td><td>the reward composition — content (the gauntlet math stays)</td></tr><tr><td><code>proposal.seed_terms</code> corpus</td><td><code>Op.make</code> list</td><td><code>lawdata.SEED_TERMS</code> specs</td><td>yes</td><td>the curated seed programs — content</td></tr><tr><td><code>proposal.schema_candidates</code> grammar</td><td><code>Op.make</code> table</td><td><code>lawdata.GRAMMAR_SCHEMAS</code> spec rows</td><td>yes</td><td>the algebraic-identity schema library — content</td></tr><tr><td><code>shape_proposal.schemas()</code> library</td><td><code>Op.make</code> table</td><td><code>lawdata.SHAPE_SCHEMAS</code> spec rows</td><td>yes</td><td>the shape-aware schema library — content</td></tr><tr><td><code>impact.new_laws()</code> candidates</td><td><code>R(...)</code> call list</td><td><code>lawdata.CANDIDATE_LAWS</code> spec rows</td><td>yes</td><td>the 11 proposed laws — content (the <code>Rewrite</code> mint + tags stay code)</td></tr><tr><td><code>impact.synthetic_cases()</code> corpus</td><td><code>Op.make</code> list</td><td><code>lawdata.SYNTHETIC_CASES</code> <code>(name, spec, var names)</code> rows</td><td>yes</td><td>the per-law witness terms — content (the random <code>feed</code> stays code)</td></tr><tr><td><code>meta.COHERENT_RULE_NAMES</code></td><td>literal frozenset</td><td><code>mlopt_core.lawdata.COHERENT_RULE_NAMES</code></td><td>yes</td><td>the coherence classification — content</td></tr><tr><td><code>meta._AC_IDENTITY</code> / <code>_ASSOC_ONLY</code></td><td>literals</td><td><code>mlopt_core.lawdata.AC_IDENTITY</code> / <code>ASSOC_ONLY</code></td><td>yes</td><td>the canonicalizer&#39;s monoid vocabulary — content</td></tr><tr><td><code>meta._LEAF_SHAPES</code> / <code>_ATTR_POOL</code></td><td>literal tuples</td><td><code>mlopt_core.lawdata.INSTANTIATE_*</code></td><td>yes</td><td>the candidate-instantiation bank — content</td></tr><tr><td><code>arena.ACTIONS</code></td><td>registry dict</td><td>unchanged</td><td>already data</td><td>already the action registry — not duplicated</td></tr><tr><td><code>arena.FixedRule</code> playbook</td><td>injected <code>Action</code> iterable</td><td>unchanged</td><td>already data</td><td>the playbook is caller-authored (<code>moves</code> param) — <code>FixedRule</code> is a replay mechanism over injected data; the ingest-first + guard-conditional ordering is policy logic (code)</td></tr><tr><td><code>workload_gen</code> census pools / mutation probabilities</td><td>derived statistics + <code>0.25</code>/<code>0.6</code> draws</td><td>unchanged</td><td>no</td><td>census pools are <em>measured</em> data (recomputed from the corpus), not authored content; the mutation mix is a strategy parameter, not a vocabulary — flagged, not moved (see below)</td></tr><tr><td><code>pipeline._POINTWISE</code> / <code>_VIEW_OPS</code></td><td>sorted tuples</td><td>unchanged</td><td>already data</td><td>opmeta projections since round 1 (<code>POINTWISE_BINARY_OPS</code> / <code>GENERATOR_VIEW_OPS</code>)</td></tr><tr><td><code>pipeline._RECOGNIZERS</code></td><td>hook table</td><td>unchanged</td><td>no</td><td>recognizers map signatures to <em>functions</em> — a hook, not a record</td></tr><tr><td><code>evidence</code> column/SQL vocabulary</td><td>literal lists</td><td>unchanged</td><td>no</td><td>store schema — the database contract, not player content</td></tr><tr><td>budgets (<code>_MAX_*</code>, <code>_RTOL</code>, <code>_TOL</code>, iteration/node caps)</td><td>literals</td><td>unchanged</td><td>no</td><td>resource knobs, not learnable content</td></tr></tbody></table><h2 id="consistency-test-—-tests-test-lawdata-py-27-tests" tabindex="-1">Consistency test — <code>tests/test_lawdata.py</code> (27 tests) <a class="header-anchor" href="#consistency-test-—-tests-test-lawdata-py-27-tests" aria-label="Permalink to “Consistency test — tests/test_lawdata.py (27 tests)”">​</a></h2><p>Same shape as <code>test_opmeta.py</code>&#39;s projection checks:</p><ul><li>every consumer name <strong>is</strong> the data object (<code>is</code>, not <code>==</code>) — the anti-drift guarantee across all 14 consumers;</li><li><code>COHERENT_RULE_NAMES ⊆</code> the real law universe (shipped rules + scan rules + the carrier modules&#39; rules, enumerated through the same <code>meta.module_rules</code> seam the engine uses — never a hand list);</li><li><code>AC_IDENTITY ⊆ COMMUTATIVE_OPS</code> (the registry projection);</li><li><code>ATTR_KIND_OVERRIDES</code> references only declared attrs/kinds; every tuple source is a registered op with valid attrs;</li><li><code>GENERATOR_ORDER</code> names the five pipeline sources + <code>build</code>, disjoint from <code>CORPUS_ARMS</code>; <code>PRIOR_WEIGHTS</code> / <code>REFEREE_SCORE</code> / <code>ARENA_REWARD</code> carry exactly the keys the consumers read;</li><li>each term-spec table resolves to the expected count/labels/family and the right leaf types (concrete <code>Var</code>/<code>Param</code> for seeds and the grammar; metavars for the schema/candidate libraries).</li></ul><h2 id="gates" tabindex="-1">Gates <a class="header-anchor" href="#gates" aria-label="Permalink to “Gates”">​</a></h2><p><code>ruff check</code>, <code>ruff format --check</code>, <code>ty check</code>, <code>vulture</code> and the radon ratchet (no baseline change — each converted function is a <code>map</code> over a data table plus a row resolver under the threshold). Scoped pytest on every touched consumer&#39;s test files — <code>test_lawdata</code> (27 new), <code>test_opmeta*</code>, <code>test_meta*</code>, <code>test_synthesis_seeds</code>, <code>test_intake_defects</code>, <code>test_law_view_oracle</code>, <code>test_discovery_oracle</code>, <code>test_discovery_verifier</code>, <code>test_discovery_proposal</code>, <code>test_discovery_impact</code>, <code>test_discovery_families</code>, <code>test_discovery_coherence*</code>, <code>test_discovery_meta_game</code>, <code>test_discovery_arena</code>, <code>test_discovery_intake</code>, <code>test_discovery_climb_a1/a2/b</code>, <code>test_discovery_experiments</code> (gap/grammar arcs), <code>test_discovery_gauntlet</code>, <code>test_discovery_zoo</code>, <code>test_discovery_emit</code>, <code>test_discovery_pipeline</code>, <code>test_discovery_synthesis</code>, <code>test_discovery_autocond</code>, <code>test_discovery_shippable_audit</code>, <code>test_law_order</code>, <code>test_cond_laws</code>, <code>test_law_pipeline_typed</code> — all green (1300+ tests).</p><h2 id="honest-boundaries" tabindex="-1">Honest boundaries <a class="header-anchor" href="#honest-boundaries" aria-label="Permalink to “Honest boundaries”">​</a></h2><ul><li><strong>The attr-domain generators stayed code.</strong> <code>oracle._attr_options</code> / <code>gap_gen._attr_candidates</code> / <code>gap_gen._op_attr_candidates</code> compute domains <em>from operand shape</em> — they are enumeration algorithms that read the moved static banks, not tables. Moving them would mean a hook registry, exactly the indirection this pass exists to remove.</li><li><strong><code>workload_gen</code>&#39;s mutation mix stayed.</strong> The <code>0.25</code>/<code>0.6</code> strategy draws are player-visible policy numbers, but they sit inside one RNG-consuming expression; the census pools they feed are <em>derived</em> statistics. Moving them is a policy-extraction question (which object owns a learned mutator), not a table move.</li><li><strong><code>meta_game</code>&#39;s <code>build</code> arm inventory is data; its legality is code.</strong> The action grammar (tree-filling, side budgets, <code>actions()</code>) is the referee&#39;s machinery — algorithms.</li><li><strong>Budgets stayed.</strong> <code>meta._MAX_INSTANTIATIONS</code>, the iteration/node caps, <code>_RTOL</code>/<code>_TOL</code> are resource knobs, not learnable content.</li><li><strong><code>object_synthesis.py</code> was excluded</strong> — a sibling effort owns it; this pass only <em>consumes</em> its <code>term_from_spec</code> DSL.</li><li><strong>Laws stay laws.</strong> <code>CANDIDATE_LAWS</code> moved the <em>records</em>; the <code>Rewrite</code> mint, tags and bodies are the engine&#39;s replayable objects.</li></ul>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};